import sys, json
sys.path.insert(0, '/tmp/kin')
from data import rows, EXCLUDED

def fit_full(pts):
    # Profile over Km: for fixed Km, best Vmax is closed-form (linear LS); minimise SSR over log Km
    def best_v(km):
        num = sum(v * s / (km + s) for s, v in pts)
        den = sum((s / (km + s)) ** 2 for s, v in pts)
        vmax = num / den
        ssr = sum((v - vmax * s / (km + s)) ** 2 for s, v in pts)
        return vmax, ssr
    return golden(lambda lk: best_v(10 ** lk)[1], -2, 5, best_v)

def fit_km_only(pts, vmax):
    def ssr(km):
        return sum((v - vmax * s / (km + s)) ** 2 for s, v in pts)
    return golden(lambda lk: ssr(10 ** lk), -2, 5, lambda km: (vmax, ssr(km)))

def golden(f, a, b, final):
    # coarse grid then golden refine on log scale
    n = 2000
    grid = [a + (b - a) * i / n for i in range(n + 1)]
    best = min(grid, key=f)
    i = grid.index(best)
    lo, hi = grid[max(i - 1, 0)], grid[min(i + 1, n)]
    g = (5 ** 0.5 - 1) / 2
    c, d = hi - g * (hi - lo), lo + g * (hi - lo)
    for _ in range(200):
        if f(c) < f(d):
            hi = d
        else:
            lo = c
        c, d = hi - g * (hi - lo), lo + g * (hi - lo)
    lk = (lo + hi) / 2
    km = 10 ** lk
    vmax, ssr = final(km)
    return vmax, km, ssr

conds = {}
for sid, cond, s, r, src in rows:
    if sid in EXCLUDED:
        continue
    if cond == 'C6':
        r = r * 2.0  # MM-5 made at 1:1000 instead of 1:500 -> rates x (1000/500)
    conds.setdefault(cond, []).append((s, r))

out = {}
for c in ['C1', 'C4', 'C5', 'C6', 'C7']:
    vmax, km, ssr = fit_full(conds[c])
    out[c] = (vmax, km)
    print(c, 'n=%d' % len(conds[c]), 'Vmax=%.5f uM/s' % vmax, 'Km=%.3f uM' % km, 'SSR=%.3g' % ssr)

# inhibitor conditions: Vmax fixed to the matching no-inhibitor condition (C2 -> C7 at pH 6.5/25C; C3 -> C6 at pH 8/37C)
for c, ref in [('C2', 'C7'), ('C3', 'C6')]:
    vmax = out[ref][0]
    km_app, ssr = None, None
    vmax_c, km_app, ssr = fit_km_only(conds[c], vmax)
    out[c] = (vmax, km_app)
    print(c, 'n=%d' % len(conds[c]), 'Vmax(fixed from %s)=%.5f' % (ref, vmax), 'apparent Km=%.3f uM' % km_app, 'SSR=%.3g' % ssr)

json.dump({k: list(v) for k, v in out.items()}, open('/tmp/kin/fits.json', 'w'), indent=1)

